cScan(CBOUND,i=>{CGRID[i]=0;CCLS[i]=2});
{const cls={walk:1,turf:3,dirt:4,parking:5,plaza:6,pond:7};for(const k in cls){if(!CG[k])continue;const T=new Uint8Array(CGW*CGH);CG[k].forEach(o=>cScan(o.P,i=>{T[i]^=1}));for(let i=0;i<T.length;i++)if(T[i]&&CCLS[i])CCLS[i]=cls[k]}}
