const cFree=(x,y)=>{const c=Math.floor(x*CR),r=Math.floor(y*CR);return c>=0&&r>=0&&c<CGW&&r<CGH&&!CGRID[r*CGW+c]};
const cCls=(x,y)=>{const c=Math.floor(x*CR),r=Math.floor(y*CR);return c>=0&&r>=0&&c<CGW&&r<CGH?CCLS[r*CGW+c]:0};
