    if(x<-1||y<-1||x>CD.W+1||y>CD.H+1)continue;const c=Math.floor(x*CR),r2=Math.floor(y*CR);if(c>=0&&r2>=0&&c<CGW&&r2<CGH&&CCLS[r2*CGW+c])continue;
