  white:{wall:'#EEF0F1',roof:'#E1E4E6',win:'#86A6C6',fr:'#FFFFFF',st:'win'},
  beige:{wall:'#E4D3B7',roof:'#F4EFE7',win:'#6F8DAE',fr:'#FFF8EC',st:'win'},
  band:{wall:'#EDE6DA',roof:'#E2E4E4',win:'#5C5F66',st:'band'},
  glassgrey:{wall:'#9FB6C7',roof:'#DDE2E6',st:'glass'},
  eglass:{wall:'#A9C8DC',roof:'#D8DCDF',st:'glass',trim:'#B8674B'},
  bluegrey:{wall:'#E8ECEF',roof:'#7F97B0',win:'#6D8AAB',fr:'#FFFFFF',st:'win'},
  dark:{wall:'#8E9398',roof:'#6E7378',win:'#A9C7DE',fr:'#C9CED2',st:'win'},
  gym:{wall:'#E1E4E7',roof:'#D3D8DC',win:'#9BB6CE',st:'strip',deco:'sky'},
  orange:{wall:'#F0F1F2',roof:'#E3E6E8',st:'louver'},
  brown:{wall:'#8A5A3C',roof:'#A87A58',st:'plain'},
  brickrib:{wall:'#C98C73',roof:'#E6E3DF',st:'rib'},
  bluetop:{wall:'#E9EDF0',roof:'#8FC3E6',win:'#7F9FBF',fr:'#FFFFFF',st:'win',deco:'glassroof'},
  frame:{wall:'#F1F2F3',roof:'#F7F8F8',win:'#8FA9C2',fr:'#FFFFFF',st:'win',ring:true},
  curveglass:{wall:'#A9CADF',roof:'#E4E9EC',st:'curve'},
  libglass:{wall:'#8DBAD9',roof:'#DDE2E5',st:'glass'}
